from pathlib import Path
import re

ROOT = Path('.')

# Shared presentation helpers for the non-technical detail surface.
helper_path = ROOT / 'apps/mobile/src/flows/installations/diagnosticPresentation.ts'
helper_path.write_text('''import type { Translate, TranslationKey } from '../../app/i18n.js';\nimport type { HardwareDiagnosticSnapshot } from '../hardware-setup/schemas.js';\n\ntype DiagnosticDetails = HardwareDiagnosticSnapshot['diagnostics'];\n\nconst diagnosticReasonKeys = new Set([\n  'ab', 'abh', 'b', 'bf', 'bl', 'blh', 'bm', 'bo', 'boot', 'bs', 'cv', 'ib',\n  'mc', 'mx', 'ok', 'pt', 'rl', 'se', 'st', 'ta', 'tm', 'tr', 'ts'\n]);\n\nexport const formatDiagnosticDuration = (durationMs: number): string => {\n  const totalSeconds = Math.max(0, Math.trunc(durationMs / 1000));\n  if (totalSeconds < 60) return `${totalSeconds} s`;\n  const totalMinutes = Math.floor(totalSeconds / 60);\n  const seconds = totalSeconds % 60;\n  if (totalMinutes < 60) {\n    return seconds === 0 ? `${totalMinutes} min` : `${totalMinutes} min ${seconds} s`;\n  }\n  const hours = Math.floor(totalMinutes / 60);\n  const minutes = totalMinutes % 60;\n  return minutes === 0 ? `${hours} h` : `${hours} h ${minutes} min`;\n};\n\nexport const formatDiagnosticUptimeAge = (\n  valueUptimeMs: number | null | undefined,\n  currentUptimeSec: number | null | undefined,\n  missing: string,\n  t: Translate\n): string => {\n  if (valueUptimeMs == null) return missing;\n  if (currentUptimeSec == null || !Number.isFinite(currentUptimeSec)) {\n    return t('hardware.diagnostics.uptimeAt', {\n      duration: formatDiagnosticDuration(valueUptimeMs)\n    });\n  }\n  return t('hardware.diagnostics.ageAgo', {\n    duration: formatDiagnosticDuration(currentUptimeSec * 1000 - valueUptimeMs)\n  });\n};\n\nexport const formatDiagnosticReason = (reason: string, t: Translate): string =>\n  diagnosticReasonKeys.has(reason)\n    ? t(`hardware.diagnosticsReason.${reason}` as TranslationKey)\n    : reason;\n\nexport const formatBleDataState = (diagnostics: DiagnosticDetails, t: Translate): string => {\n  const hasRuleValue =\n    typeof diagnostics.lastControlValue === 'number' &&\n    Number.isFinite(diagnostics.lastControlValue) &&\n    typeof diagnostics.lastSeenUptimeMs === 'number' &&\n    Number.isFinite(diagnostics.lastSeenUptimeMs);\n\n  if (diagnostics.dataState === 'cv' && diagnostics.lastReason !== 'cv' && hasRuleValue) {\n    return '-';\n  }\n  return formatDiagnosticReason(diagnostics.dataState, t);\n};\n\nexport const formatDiagnosticNumber = (\n  value: number | null | undefined,\n  suffix: string,\n  missing: string,\n  digits = 1\n): string => (value == null || !Number.isFinite(value) ? missing : `${value.toFixed(digits)}${suffix}`);\n\nexport const formatRelayState = (value: boolean | null | undefined, missing: string): string =>\n  value == null ? missing : value ? 'ON' : 'OFF';\n''')

screen_path = ROOT / 'apps/mobile/src/screens/InstallationDetailScreen.tsx'
screen = screen_path.read_text()
screen = screen.replace("import {\n  formatInstallationMetric,\n  INSTALLATION_MODE_KEYS,\n  installationThresholdSummary\n} from '../flows/installations/presentation.js';", "import { INSTALLATION_MODE_KEYS } from '../flows/installations/presentation.js';")
screen = screen.replace("import { InstallationRuntimeControls } from './InstallationRuntimeControls.js';\n", '')
insert_after = "import { installationRecoveryState } from '../flows/installations/healthRecovery.js';\n"
helper_import = "import {\n  formatBleDataState,\n  formatDiagnosticNumber,\n  formatDiagnosticReason,\n  formatDiagnosticUptimeAge,\n  formatRelayState\n} from '../flows/installations/diagnosticPresentation.js';\n"
if helper_import not in screen:
    screen = screen.replace(insert_after, insert_after + helper_import)

screen = re.sub(r"\nconst configuredThresholdSummary = \(installation: ClimateInstalledAutomation\) =>\n  installationThresholdSummary\(installation\);\n", "\n", screen, count=1)
screen = screen.replace("  const isPaused = scriptMatch === 'matched' && control?.automationMode === 'manual';\n  const canToggleAutomation =\n    scriptMatch === 'matched' &&\n    (control?.automationMode === 'auto' || control?.automationMode === 'manual');\n", '')

old_logic = "  const relayState =\n    control?.relayOn ?? snapshot?.plug?.relayState ?? snapshot?.diagnostics.relayState;\n  const purposeLabel =\n"
new_logic = "  const missing = t('common.missing');\n  const diagnostics = snapshot?.diagnostics;\n  const shellyRelayState = snapshot?.plug?.relayState ?? control?.relayOn;\n  const diagnosticSensorLabel =\n    snapshot?.sensor?.displayName ??\n    snapshot?.sensor?.runtimeAddress ??\n    installation.config.sensor.displayName ??\n    installation.config.sensor.runtimeAddress ??\n    missing;\n  const purposeLabel =\n"
if old_logic not in screen:
    raise SystemExit('detail logic anchor missing')
screen = screen.replace(old_logic, new_logic, 1)

start = screen.index('  return (\n    <main className="demo-shell installation-detail-shell app-bottom-nav-shell">')
nav_marker = '      <AppBottomNavigation\n'
nav = screen.index(nav_marker, start)
new_body = '''  return (\n    <main className="demo-shell installation-detail-shell app-bottom-nav-shell">\n      <section className="installation-detail-grid" aria-label={t('detail.currentState')}>\n        <article className="automation-card installation-detail-identity">\n          <div className="installation-detail-identity__copy">\n            <h1>{installation.shelly.name}</h1>\n            <p className="installation-detail-purpose">{purposeLabel}</p>\n          </div>\n        </article>\n\n        {visibleRecovery && recoveryCopy && (\n          <article className="automation-card installation-detail-recovery" role="status">\n            <div className="installation-section-heading">\n              <div>\n                <p className="automation-card__eyebrow">\n                  {installationHealthCopy[locale].eyebrow}\n                </p>\n                <h2>{recoveryCopy.title}</h2>\n              </div>\n            </div>\n            <p className="installation-detail-note">{recoveryCopy.description}</p>\n            <div className="installation-detail-actions">\n              <button\n                className={\n                  visibleRecovery.action === 'resume'\n                    ? 'primary-action'\n                    : 'secondary-action'\n                }\n                type="button"\n                disabled={\n                  visibleRecovery.action === 'resume'\n                    ? automationAction.isPending\n                    : diagnosticsQuery.isFetching || controlQuery.isFetching\n                }\n                onClick={() => {\n                  if (visibleRecovery.action === 'resume') {\n                    automationAction.mutate('recover', {\n                      onSuccess: () => pushToast('ok', t('detail.resumeSuccess'))\n                    });\n                    return;\n                  }\n                  void refreshAll();\n                }}\n              >\n                {visibleRecovery.action === 'resume' && automationAction.isPending\n                  ? t('detail.changingState')\n                  : visibleRecovery.action === 'refresh' &&\n                      (diagnosticsQuery.isFetching || controlQuery.isFetching)\n                    ? t('common.refreshing')\n                    : recoveryCopy.action}\n              </button>\n            </div>\n          </article>\n        )}\n\n        <article className="automation-card installation-detail-config">\n          <div className="installation-section-heading">\n            <h2>{t('detail.automation')}</h2>\n            <button\n              aria-label={scriptCopy.action}\n              className="icon-action"\n              disabled={scriptMatch !== 'matched' || deleteMutation.isPending}\n              title={scriptCopy.action}\n              type="button"\n              onClick={() => setScriptOpen(true)}\n            >\n              <IconCode className="icon-action__svg" aria-hidden="true" />\n            </button>\n          </div>\n          <dl className="automation-summary installation-detail-summary">\n            <div>\n              <dt>{t('hardware.metrics.mode')}</dt>\n              <dd>{t(INSTALLATION_MODE_KEYS[installation.config.rule.mode])}</dd>\n            </div>\n            <div>\n              <dt>{t('hardware.metrics.reason')}</dt>\n              <dd>{diagnostics ? formatDiagnosticReason(diagnostics.lastReason, t) : missing}</dd>\n            </div>\n            <div>\n              <dt>{t('hardware.metrics.relayRule')}</dt>\n              <dd>{formatRelayState(diagnostics?.relayState, missing)}</dd>\n            </div>\n            <div>\n              <dt>{t('hardware.metrics.shellyRelay')}</dt>\n              <dd>{formatRelayState(shellyRelayState, missing)}</dd>\n            </div>\n          </dl>\n        </article>\n\n        <article className="automation-card installation-detail-sensor">\n          <div className="installation-section-heading">\n            <h2>{t('hardware.diagnostics.groupSensor')}</h2>\n          </div>\n          <dl className="automation-summary installation-detail-summary">\n            <div>\n              <dt>{t('hardware.metrics.thermometer')}</dt>\n              <dd>{diagnosticSensorLabel}</dd>\n            </div>\n            <div>\n              <dt>{t('hardware.metrics.lastMeasurement')}</dt>\n              <dd>{formatDiagnosticUptimeAge(diagnostics?.lastSeenUptimeMs, snapshot?.time.uptimeSec, missing, t)}</dd>\n            </div>\n            <div>\n              <dt>{t('hardware.metrics.lastBlePacket')}</dt>\n              <dd>{formatDiagnosticUptimeAge(diagnostics?.lastPacketSeenUptimeMs, snapshot?.time.uptimeSec, missing, t)}</dd>\n            </div>\n            <div>\n              <dt>{t('hardware.metrics.battery')}</dt>\n              <dd>{formatDiagnosticNumber(diagnostics?.lastBattery, '%', missing, 0)}</dd>\n            </div>\n            <div>\n              <dt>RSSI</dt>\n              <dd>{formatDiagnosticNumber(diagnostics?.lastRssi, ' dBm', missing, 0)}</dd>\n            </div>\n            <div>\n              <dt>{t('hardware.metrics.dataBle')}</dt>\n              <dd>{diagnostics ? formatBleDataState(diagnostics, t) : missing}</dd>\n            </div>\n          </dl>\n        </article>\n\n        <article className="automation-card installation-detail-shelly">\n          <div className="installation-section-heading">\n            <h2>{t('hardware.diagnostics.groupShelly')}</h2>\n          </div>\n          <dl className="automation-summary installation-detail-summary">\n            <div>\n              <dt>{t('hardware.metrics.current')}</dt>\n              <dd>{formatDiagnosticNumber(snapshot?.plug?.currentA, ' A', missing, 2)}</dd>\n            </div>\n            <div>\n              <dt>{t('hardware.metrics.plugTemperature')}</dt>\n              <dd>{formatDiagnosticNumber(snapshot?.plug?.deviceTemperatureC, '°C', missing, 1)}</dd>\n            </div>\n            <div>\n              <dt>{t('hardware.shelly.clockSync')}</dt>\n              <dd>{snapshot ? (snapshot.time.isSynced ? 'OK' : t('hardware.status.unsynced')) : missing}</dd>\n            </div>\n          </dl>\n        </article>\n\n        <article className="automation-card installation-detail-management">\n          <div className="installation-detail-actions installation-detail-management__actions">\n            <button className="secondary-action" type="button" onClick={() => setDiagnosticsOpen(true)}>\n              {t('common.diagnostics')}\n            </button>\n            <button\n              className="secondary-action secondary-action--danger"\n              type="button"\n              disabled={deleteMutation.isPending}\n              onClick={() => setDeleteOpen(true)}\n            >\n              {deleteCopy.action}\n            </button>\n          </div>\n        </article>\n\n        <ShellyLedSettingsCard installation={installation} onFeedback={pushToast} />\n      </section>\n\n'''
screen = screen[:start] + new_body + screen[nav:]
screen_path.write_text(screen)

# Keep the modal truly technical now that sensor / device-health fields live on detail.
modal_path = ROOT / 'apps/mobile/src/screens/InstallationDiagnosticsModal.tsx'
modal = modal_path.read_text()
modal = re.sub(r"\nconst formatEnergy = \(value: number \| null \| undefined, missing: string\): string => \{.*?\n\};\n", "\n", modal, count=1, flags=re.S)
# Replace merged script state with explicit runtime + RPC rows.
old = '''            <DiagnosticRow\n              label={t('hardware.rule.script')}\n              value={\n                resourceScriptRunning === true\n                  ? t('hardware.status.running')\n                  : resourceScriptRunning === false\n                    ? t('hardware.diagnostics.scriptMissingConfirm')\n                    : missing\n              }\n              tone={resourceScriptRunning === false ? 'warning' : 'normal'}\n            />'''
new = '''            <DiagnosticRow\n              label={t('hardware.rule.script')}\n              value={\n                script?.running === true\n                  ? t('hardware.status.running')\n                  : script?.running === false\n                    ? t('hardware.diagnostics.scriptMissingConfirm')\n                    : missing\n              }\n              tone={script?.running === false ? 'warning' : 'normal'}\n            />\n            <DiagnosticRow\n              label={t('hardware.diagnostics.scriptRpcState')}\n              value={\n                resources?.script?.running === true\n                  ? 'RUNNING'\n                  : resources?.script?.running === false\n                    ? 'STOPPED'\n                    : missing\n              }\n            />'''
if old not in modal:
    raise SystemExit('modal script row anchor missing')
modal = modal.replace(old, new, 1)
modal = modal.replace("  const plug = snapshot?.plug;\n", '')
modal = modal.replace("  const resourceScriptRunning = resources?.script?.running ?? script?.running ?? null;\n\n", '')
# Remove Sensor technical group entirely.
modal = re.sub(r"\n          <TechnicalGroup\n            title=\{t\('hardware\.diagnostics\.groupSensor'\)\}.*?</TechnicalGroup>", "", modal, count=1, flags=re.S)
# Replace Shelly group with technical-only device internals.
modal = re.sub(r"\n          <TechnicalGroup\n            title=\{t\('hardware\.diagnostics\.groupShelly'\)\}.*?</TechnicalGroup>", '''\n          <TechnicalGroup\n            title={t('hardware.diagnostics.groupShelly')}\n            description={t('hardware.diagnostics.groupShellyHint')}\n          >\n            <DiagnosticRow\n              label={t('hardware.diagnostics.deviceRamFree')}\n              value={formatBytes(resources?.system?.ramFreeBytes, missing)}\n            />\n            <DiagnosticRow\n              label={t('hardware.diagnostics.deviceRamTotal')}\n              value={formatBytes(resources?.system?.ramSizeBytes, missing)}\n            />\n            <DiagnosticRow\n              label={t('hardware.metrics.clockShelly')}\n              value={snapshot.time.localTime ?? missing}\n            />\n          </TechnicalGroup>''', modal, count=1, flags=re.S)
modal_path.write_text(modal)

# Runtime control component is no longer part of detail UX.
runtime_controls = ROOT / 'apps/mobile/src/screens/InstallationRuntimeControls.tsx'
if runtime_controls.exists():
    runtime_controls.unlink()

# Detail tests: replace the old duplicate/control-heavy test with the new product contract.
test_path = ROOT / 'apps/mobile/src/__tests__/automation-detail.test.tsx'
test = test_path.read_text()
pattern = re.compile(r"  it\('shows Shelly runtime and safely pauses and resumes the exact installed script', async \(\) => \{.*?\n  \}\);\n\n  it\('opens auto-refreshing scoped technical diagnostics", re.S)
replacement = '''  it('shows unique diagnostic detail without duplicating dashboard controls or climate values', async () => {\n    const saved = installation();\n    useInstalledAutomationStore.getState().upsertInstallation(saved);\n    installShellyFetchMock();\n    const { onBack, onNavigateDashboard, onOpenSettings } = renderDetail(saved.id);\n\n    expect(await screen.findByRole('heading', { name: 'Salon' })).toBeVisible();\n    const identityCard = screen.getByRole('heading', { name: 'Salon' }).closest('article');\n    expect(identityCard).toHaveClass('installation-detail-identity');\n    expect(screen.getByText('Sterowanie temperaturą')).toBeVisible();\n\n    const automationCard = screen.getByRole('heading', { name: 'Automatyka' }).closest('article');\n    expect(automationCard).not.toBeNull();\n    expect(within(automationCard!).getByText('Przyczyna')).toBeVisible();\n    expect(within(automationCard!).getByText('Przekaźnik reguły')).toBeVisible();\n    expect(within(automationCard!).getByText('Przekaźnik Shelly')).toBeVisible();\n    expect(within(automationCard!).queryByRole('button', { name: 'AUTO' })).toBeNull();\n    expect(within(automationCard!).queryByRole('button', { name: 'MANUAL' })).toBeNull();\n    expect(within(automationCard!).queryByRole('button', { name: 'ON' })).toBeNull();\n    expect(within(automationCard!).queryByRole('button', { name: 'OFF' })).toBeNull();\n\n    const sensorCard = screen.getByRole('heading', { name: 'Czujnik' }).closest('article');\n    expect(sensorCard).not.toBeNull();\n    expect(within(sensorCard!).getByText('Przedpokój')).toBeVisible();\n    expect(within(sensorCard!).getByText('91%')).toBeVisible();\n    expect(within(sensorCard!).getByText('-51 dBm')).toBeVisible();\n\n    const shellyCard = screen.getByRole('heading', { name: 'Shelly' }).closest('article');\n    expect(shellyCard).not.toBeNull();\n    expect(within(shellyCard!).getByText('0.20 A')).toBeVisible();\n    expect(within(shellyCard!).getByText('32.4°C')).toBeVisible();\n    expect(within(shellyCard!).getByText('OK')).toBeVisible();\n\n    expect(screen.queryByText('21.4°C')).toBeNull();\n    expect(screen.queryByText('55.2%')).toBeNull();\n    expect(screen.queryByText('1.31 kPa')).toBeNull();\n    expect(screen.queryByText('19°C / 20°C')).toBeNull();\n\n    fireEvent.click(screen.getByRole('button', { name: 'Termometry' }));\n    expect(onNavigateDashboard).toHaveBeenCalledWith('time');\n    expect(onBack).not.toHaveBeenCalled();\n    fireEvent.click(screen.getByRole('button', { name: 'Ustawienia' }));\n    expect(onOpenSettings).toHaveBeenCalledTimes(1);\n  });\n\n  it('opens auto-refreshing scoped technical diagnostics'''
test, n = pattern.subn(replacement, test, count=1)
if n != 1:
    raise SystemExit('detail primary test replacement failed')
# Technical modal assertions now reflect deep technical only.
test = test.replace("    expect(within(dialog).getByText('Bateria')).toBeInTheDocument();\n    expect(within(dialog).getByText('RSSI')).toBeInTheDocument();\n", "    expect(within(dialog).getByText('Stan RPC skryptu')).toBeVisible();\n")
test = test.replace("    expect(within(dialog).queryByText('Wyjście', { exact: true })).toBeNull();\n", "    expect(within(dialog).queryByText('Wyjście', { exact: true })).toBeNull();\n    expect(within(dialog).queryByText('Bateria', { exact: true })).toBeNull();\n    expect(within(dialog).queryByText('RSSI', { exact: true })).toBeNull();\n    expect(within(dialog).queryByText('Prąd', { exact: true })).toBeNull();\n")
test_path.write_text(test)

# Tokenized layout styles: compact identity card, full-width recovery/management; remove climate-only overrides.
theme_path = ROOT / 'apps/mobile/src/theme/theme.css'
theme = theme_path.read_text()
theme += '''\n\n/* Climate installation detail: identity and diagnostics-first layout. */\n.installation-detail-identity,\n.installation-detail-recovery,\n.installation-detail-management {\n  grid-column: 1 / -1;\n}\n\n.installation-detail-identity__copy {\n  display: grid;\n  gap: var(--lcl-spacing-xs);\n}\n\n.installation-detail-identity h1 {\n  font-size: var(--lcl-font-size-2xl);\n  line-height: var(--lcl-line-height-tight);\n  margin: 0;\n}\n\n.installation-detail-management__actions {\n  border-top: 0;\n  padding-top: 0;\n}\n'''
theme_path.write_text(theme)

print('Implemented diagnostics-first climate detail layout')
